package org.jlinalg.enrichment;

import static org.junit.jupiter.api.Assertions.*;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import static org.jlinalg.enrichment.FumaCelltypeAnalysis.*;

class FumaCelltypeAnalysisTest {
    private static final Limits LIMITS=new Limits(1000,1000,1000000);
    private static final Cell A=new Cell("D","A"),B=new Cell("D","B");
    private static Fit fit(double p){return new Fit(200,.1,.2,.01,p);}
    private static Fit absent(){return new Fit(-1,Double.NaN,Double.NaN,Double.NaN,Double.NaN);}
    private static List<Marginal> marginal(Cell... cells){var rows=new ArrayList<MarginalInput>();for(var cell:cells)rows.add(new MarginalInput(cell,fit(1e-10)));return FumaCelltypeAnalysis.marginal(rows,Correction.BONFERRONI,LIMITS,()->{});}
    private static WithinResult within(double p,double q){return FumaCelltypeAnalysis.within(marginal(A,B),List.of(new Pair(1,A,fit(p),B,fit(q))),LIMITS,()->{});}
    private static List<String> states(WithinResult result,int row){return result.summary().get(row).states();}
    @Test void completeCorrectionsRetainDatasetAndAcrossDatasetFamilies(){var m=FumaCelltypeAnalysis.marginal(List.of(new MarginalInput(new Cell("Z","B"),fit(.03)),new MarginalInput(new Cell("A","C"),fit(.04)),new MarginalInput(new Cell("Z","A"),fit(.01)),new MarginalInput(new Cell("A","D"),fit(.05))),Correction.BH,LIMITS,()->{});assertEquals(List.of("Z:A","Z:B","A:C","A:D"),m.stream().map(r->r.cell().dataset()+":"+r.cell().label()).toList());assertArrayEquals(new double[]{.02,.03,.05,.05},m.stream().mapToDouble(Marginal::adjustedPerDataset).toArray(),1e-16);assertArrayEquals(new double[]{.04,.05,.05,.05},m.stream().mapToDouble(Marginal::adjustedAcrossDatasets).toArray(),1e-16);var w=FumaCelltypeAnalysis.within(m,List.of(),LIMITS,()->{});assertEquals(1,w.summary().size());assertFalse(w.sourceSummaryWritten());}
    @Test void correctionZeroOneEmptyAndRankBoundaries(){for(Correction c:Correction.values()){assertArrayEquals(new double[0],adjust(new double[0],c,LIMITS,()->{}));double[] p=adjust(new double[]{0,1},c,LIMITS,()->{});assertEquals(0,p[0]);assertEquals(1,p[1]);}assertArrayEquals(new double[]{.03,.04,.04},adjust(new double[]{.01,.02,.03},Correction.HOLM,LIMITS,()->{}),1e-16);assertArrayEquals(new double[]{.03,.03,.03},adjust(new double[]{.01,.02,.03},Correction.HOCHBERG,LIMITS,()->{}),1e-16);assertArrayEquals(new double[]{.03,.03,.03},adjust(new double[]{.01,.02,.03},Correction.HOMMEL,LIMITS,()->{}),1e-16);}
    @Test void strictPointZeroFiveSelectionUsesGlobalCorrection(){var m=FumaCelltypeAnalysis.marginal(List.of(new MarginalInput(A,fit(.025)),new MarginalInput(B,fit(.025))),Correction.BONFERRONI,LIMITS,()->{});assertTrue(FumaCelltypeAnalysis.within(m,List.of(),LIMITS,()->{}).summary().isEmpty());}
    @Test void independentPairsAreRetainedForCrossDatasetAnalysis(){var r=within(1e-8,1e-8);assertEquals(List.of("indep"),states(r,0));assertEquals(List.of("indep"),states(r,1));assertEquals(1,r.retainedPairs().size());assertEquals(.8,r.pairs().get(0).firstPS());}
    @Test void jointBranchPrecedesLowProportionalSignificance(){var r=within(.2,.2);assertEquals(List.of("joint"),states(r,0));assertEquals(List.of("joint-drop"),states(r,1));assertFalse(r.summary().get(1).entersCrossDataset());}
    @Test void partialJointLowRatiosRetainSourceBranch(){var r=within(.03,.04);assertEquals(List.of("partial-joint"),states(r,0));assertEquals(List.of("joint-drop"),states(r,1));}
    @Test void mainDriverAndDroppedPartner(){var r=within(1e-8,.1);assertEquals(List.of("main"),states(r,0));assertEquals(List.of("drop"),states(r,1));assertEquals(List.of(B),r.summary().get(0).partners());}
    @Test void strongDriverAndPartialDrop(){var r=within(1e-8,.02);assertEquals(List.of("main"),states(r,0));assertEquals(List.of("partial-drop"),states(r,1));}
    @Test void partialJointBothSurviveWhenBothRatiosAtLeastPointFive(){var r=within(1e-6,1e-5);assertEquals(List.of("partial-joint"),states(r,0));assertEquals(List.of("partial-joint"),states(r,1));assertTrue(r.summary().stream().allMatch(Summary::entersCrossDataset));}
    @Test void partialJointBothAbovePointTwoDropsThePartner(){var r=within(1e-4,1e-3);assertEquals(List.of("partial-joint"),states(r,0));assertEquals(List.of("partial-joint-drop"),states(r,1));}
    @Test void moderateDriverAndNonsignificantPartnerUsesJointDrop(){var r=within(1e-3,.1);assertEquals(List.of("partial-joint"),states(r,0));assertEquals(List.of("joint-drop"),states(r,1));}
    @Test void moderateDriverAndSmallPartnerUsesPartialJointDrop(){var r=within(1e-3,.03);assertEquals(List.of("partial-joint"),states(r,0));assertEquals(List.of("partial-joint-drop"),states(r,1));}
    @Test void mainDriverSearchCanSelectSecondMarginalWithoutReorderingOutput(){var r=within(.03,1e-8);assertEquals(List.of("partial-drop"),states(r,0));assertEquals(List.of("main"),states(r,1));assertEquals(A,r.pairs().get(0).pair().first());assertEquals(B,r.summary().get(0).partners().get(0));}
    @Test void allMissingCollinearPairHasExplicitSourceLabels(){var r=FumaCelltypeAnalysis.within(marginal(A,B),List.of(new Pair(1,A,absent(),B,absent())),LIMITS,()->{});assertEquals(List.of("colinear"),states(r,0));assertEquals(List.of("colinear-drop"),states(r,1));}
    @Test void incompleteDuplicateAndUnselectedModelsAreRejected(){assertThrows(IllegalArgumentException.class,()->FumaCelltypeAnalysis.within(marginal(A,B),List.of(),LIMITS,()->{}));assertThrows(IllegalArgumentException.class,()->new Pair(1,A,absent(),B,fit(.2)));assertThrows(IllegalArgumentException.class,()->FumaCelltypeAnalysis.within(marginal(A,B),List.of(new Pair(1,A,fit(.1),new Cell("Other","B"),fit(.1))),LIMITS,()->{}));}
    @Test void zeroOverZeroIsRejectedBeforeConditionalClassification(){var m=FumaCelltypeAnalysis.marginal(List.of(new MarginalInput(A,fit(0)),new MarginalInput(B,fit(0))),Correction.BONFERRONI,LIMITS,()->{});assertThrows(IllegalArgumentException.class,()->FumaCelltypeAnalysis.within(m,List.of(new Pair(1,A,fit(0),B,fit(.1))),LIMITS,()->{}));}
    @Test void multipleDatasetSingletonsHaveNoWithinModelsButKeepSourceSummary(){var w=FumaCelltypeAnalysis.within(marginal(A,new Cell("Z","C")),List.of(),LIMITS,()->{});assertTrue(w.sourceSummaryWritten());assertTrue(w.summary().stream().allMatch(r->r.states().equals(List.of("single"))));}
    @Test void crossDatasetModelsAppendRetainedWithinPairsAndUseConditionalMeans(){Cell z=new Cell("Z","C");var w=FumaCelltypeAnalysis.within(marginal(z,A,B),List.of(new Pair(7,A,fit(1e-8),B,fit(1e-8))),LIMITS,()->{});var pairs=List.of(new Pair(2,z,fit(1e-6),A,fit(1e-4)),new Pair(3,z,fit(1e-5),B,fit(1e-3)));var means=List.of(new ConditionalAverage(z,"D",fit(1e-9)),new ConditionalAverage(A,"Z",fit(1e-8)),new ConditionalAverage(B,"Z",fit(1e-7)));var r=cross(w,pairs,means,LIMITS,()->{});assertTrue(r.sourceGateOpened());assertEquals(6,r.rows().size());assertEquals(2.0/3,r.rows().get(0).ps(),1e-15);assertEquals(.9,r.rows().get(0).averagePS(),1e-15);assertEquals(.5,r.rows().get(1).ps());assertEquals(3,r.rows().get(4).model());assertTrue(r.rows().get(4).withinDataset());assertNull(r.rows().get(4).conditionalAverage());assertTrue(Double.isNaN(r.rows().get(4).averagePS()));assertFalse(r.rows().get(4).undefinedRatio());}
    @Test void crossGateAndCompleteAveragePopulationAreEnforced(){var one=within(1e-8,.1);assertFalse(cross(one,List.of(),List.of(),LIMITS,()->{}).sourceGateOpened());Cell z=new Cell("Z","C");var w=FumaCelltypeAnalysis.within(marginal(A,z),List.of(),LIMITS,()->{});var p=List.of(new Pair(1,A,fit(.001),z,fit(.002)));assertThrows(IllegalArgumentException.class,()->cross(w,p,List.of(new ConditionalAverage(A,"Z",fit(1e-5))),LIMITS,()->{}));}
    @Test void crossZeroRatiosRemainExplicitlyUndefined(){Cell z=new Cell("Z","C");var m=FumaCelltypeAnalysis.marginal(List.of(new MarginalInput(A,fit(0)),new MarginalInput(z,fit(0))),Correction.BONFERRONI,LIMITS,()->{});var w=FumaCelltypeAnalysis.within(m,List.of(),LIMITS,()->{});var r=cross(w,List.of(new Pair(1,A,fit(0),z,fit(0))),List.of(new ConditionalAverage(A,"Z",fit(0)),new ConditionalAverage(z,"D",fit(0))),LIMITS,()->{});assertTrue(r.rows().stream().allMatch(CrossRow::undefinedRatio));assertTrue(Double.isNaN(r.rows().get(0).ps()));}
    @Test void sourcePairModelAndMarginalTieOrdersRemainStable(){Cell c=new Cell("A","X"),d=new Cell("A","Y");var m=marginal(A,B,c,d);var w=FumaCelltypeAnalysis.within(m,List.of(new Pair(9,B,fit(1e-8),A,fit(1e-8)),new Pair(2,d,fit(1e-8),c,fit(1e-8))),LIMITS,()->{});assertEquals("A",w.pairs().get(0).pair().first().dataset());assertEquals(d,w.pairs().get(0).pair().first());assertEquals(B,w.pairs().get(1).pair().first());}
    @Test void boundsCallbacksAndHommelQuadraticWorkAreChecked(){assertThrows(IllegalArgumentException.class,()->adjust(new double[]{.1,.2,.3},Correction.HOMMEL,new Limits(10,10,5),()->{}));var calls=new AtomicInteger();assertThrows(IllegalStateException.class,()->FumaCelltypeAnalysis.marginal(List.of(new MarginalInput(A,fit(.1))),Correction.BH,LIMITS,()->{if(calls.incrementAndGet()==2)throw new IllegalStateException("cancelled");}));assertThrows(IllegalArgumentException.class,()->FumaCelltypeAnalysis.within(marginal(A,B,new Cell("D","C")),List.of(),new Limits(10,1,10000),()->{}));}
    @Test void invalidFitsNamesAndRepeatedMarginalsAreRejected(){assertThrows(IllegalArgumentException.class,()->new Cell("D","Average"));assertThrows(IllegalArgumentException.class,()->new Cell("D","A:B"));assertThrows(IllegalArgumentException.class,()->fit(Double.NaN));assertThrows(IllegalArgumentException.class,()->new Fit(0,.1,.2,.01,.05));assertThrows(IllegalArgumentException.class,()->FumaCelltypeAnalysis.marginal(List.of(new MarginalInput(A,fit(.1)),new MarginalInput(A,fit(.2))),Correction.BH,LIMITS,()->{}));}
    @Test void nativeResultsAndSourceLabelsAreImmutable(){var r=within(1e-8,.1);assertThrows(UnsupportedOperationException.class,()->r.summary().clear());assertThrows(UnsupportedOperationException.class,()->r.summary().get(0).states().add("changed"));assertThrows(UnsupportedOperationException.class,()->r.summary().get(0).partners().clear());}
}
